    // Camera tracks (camera + point cloud) are project media too: one card per tracked video in the strip.
    async function syncTrackScenes() {
        const pid = currentProject?.id || "sandbox_playground";
        let tracks = [];
        try { tracks = (await fetch(`/vfx/track/list?project_id=${encodeURIComponent(pid)}`).then(r => r.json())).tracks || []; } catch (_) { return; }
        let changed = false;
        tracks.forEach(t => {
            const vtitle = (mediaVideos2D.find(v => v.id === t.video_id) || {}).title || t.video_id;
            const desc = `${t.frames} ${uiText("frames", "кадров")} · ${t.points} ${uiText("pts", "точек")}${t.focal_mm ? ` · ${Math.round(t.focal_mm)} mm` : ""}`;
            let it = mediaScenes3D.find(s => s.mode === "track" && s.videoId === t.video_id);
            if (!it) {
                mediaScenes3D.push({ id: `trk_${t.video_id}`, title: `${uiText("Track", "Трек")}: ${vtitle}`, badge: "TRACK", desc, mode: "track", videoId: t.video_id, mtime: t.mtime });
                changed = true;
            } else if (it.mtime !== t.mtime || it.desc !== desc) { it.desc = desc; it.mtime = t.mtime; changed = true; }
        });
        if (changed) { saveProject3DScenes(); try { renderTopViewportBar(); } catch (_) {} }
    }
    window.__vfxSyncTrackScenes = syncTrackScenes;
    async function activateTrackScene(scn) {
        const pid = currentProject?.id || "sandbox_playground";
        const r = await fetch("/vfx/track/activate", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ project_id: pid, video_id: scn.videoId }) }).then(x => x.json()).catch(e => ({ error: e.message }));
        if (r.error) { showToastNotification(`${uiText("Track", "Трек")}: ${r.error}`, true); return; }
        try { localStorage.removeItem("vfx_3d_lidar_deleted"); localStorage.removeItem("vfx_3d_shot_cam_deleted"); } catch (_) {}
        if (typeof onReloadSceneData === "function") await onReloadSceneData(currentProject);
        showToastNotification(uiText(`Track «${scn.title}» is in the scene: camera + point cloud`, `«${scn.title}» в сцене: камера + облако точек`));
    }
    setTimeout(() => { try { syncTrackScenes(); } catch (_) {} }, 1500);
