    // --- Storyboard Undo / Redo History (35 actions depth) ---
    let storyboardUndoStack = [];
    let storyboardRedoStack = [];

    function pushStoryboardUndoSnapshot(desc = "Storyboard edit") {
        try {
            const snap = {
                cards: JSON.parse(JSON.stringify(storyboardCards)),
                links: JSON.parse(JSON.stringify(storyboardLinks)),
                texts: JSON.parse(JSON.stringify(mediaTexts)),
                desc: desc
            };
            storyboardUndoStack.push(snap);
            if (storyboardUndoStack.length > 35) storyboardUndoStack.shift();
            storyboardRedoStack = [];
        } catch (e) {
            console.error("Failed to push storyboard undo snapshot:", e);
        }
    }

    function performStoryboardUndo() {
        if (!storyboardUndoStack || storyboardUndoStack.length === 0) {
            return false;
        }
        try {
            const currentSnap = {
                cards: JSON.parse(JSON.stringify(storyboardCards)),
                links: JSON.parse(JSON.stringify(storyboardLinks)),
                texts: JSON.parse(JSON.stringify(mediaTexts)),
                desc: "Current state"
            };
            storyboardRedoStack.push(currentSnap);
            if (storyboardRedoStack.length > 35) storyboardRedoStack.shift();

            const prevSnap = storyboardUndoStack.pop();
            storyboardCards = JSON.parse(JSON.stringify(prevSnap.cards || []));
            storyboardLinks = JSON.parse(JSON.stringify(prevSnap.links || []));
            if (Array.isArray(prevSnap.texts)) {
                mediaTexts = JSON.parse(JSON.stringify(prevSnap.texts));
                activeTextId = mediaTexts[0]?.id || null;
            }

            saveProjectTexts();
            if (typeof saveCurrentProject === "function") saveCurrentProject();
            renderMainViewport();
            renderTopViewportBar();
            if (activeTab === "storyboard" && typeof renderActiveCustomTab === "function") {
                renderActiveCustomTab();
            }
            addLog("UI", `Storyboard Undo: ${prevSnap.desc || 'restored'} (${storyboardUndoStack.length} steps left)`);
            showToastNotification(uiText(`Undo: ${prevSnap.desc || 'restored'}`, `Отменено: ${prevSnap.desc || 'раскадровка восстановлена'}`));
            return true;
        } catch (e) {
            console.error("Storyboard undo failed:", e);
            return false;
        }
    }

    function performStoryboardRedo() {
        if (!storyboardRedoStack || storyboardRedoStack.length === 0) {
            return false;
        }
        try {
            const currentSnap = {
                cards: JSON.parse(JSON.stringify(storyboardCards)),
                links: JSON.parse(JSON.stringify(storyboardLinks)),
                texts: JSON.parse(JSON.stringify(mediaTexts)),
                desc: "Current state"
            };
            storyboardUndoStack.push(currentSnap);
            if (storyboardUndoStack.length > 35) storyboardUndoStack.shift();

            const nextSnap = storyboardRedoStack.pop();
            storyboardCards = JSON.parse(JSON.stringify(nextSnap.cards || []));
            storyboardLinks = JSON.parse(JSON.stringify(nextSnap.links || []));
            if (Array.isArray(nextSnap.texts)) {
                mediaTexts = JSON.parse(JSON.stringify(nextSnap.texts));
                activeTextId = mediaTexts[0]?.id || null;
            }

            saveProjectTexts();
            if (typeof saveCurrentProject === "function") saveCurrentProject();
            renderMainViewport();
            renderTopViewportBar();
            if (activeTab === "storyboard" && typeof renderActiveCustomTab === "function") {
                renderActiveCustomTab();
            }
            addLog("UI", `Storyboard Redo: ${nextSnap.desc || 're-applied'}`);
            showToastNotification(uiText(`Redo: ${nextSnap.desc || 're-applied'}`, `Повторено: ${nextSnap.desc || 'действие раскадровки'}`));
            return true;
        } catch (e) {
            console.error("Storyboard redo failed:", e);
            return false;
        }
    }

    function autoResizeAgentInput(el, minH = 28, maxH = 82) {
        if (!el) return;
        el.style.height = "auto";
        const sh = el.scrollHeight;
        const targetH = Math.max(minH, Math.min(sh, maxH));
        el.style.height = targetH + "px";
        el.style.overflowY = sh > maxH ? "auto" : "hidden";
    }

