    function handleEditUndo() {
        if (mainViewDim === "1D" && typeof active1DUndoFn === "function") {
            if (active1DUndoFn()) {
                addLog("UI", "Undo 1D paint/crop action");
                showToastNotification(uiText("Undo (Image layer)", "Отменено (слой Image)"));
                return;
            }
        }
        if (mainViewDim === "BOARD" || activeTab === "storyboard") {
            if (performStoryboardUndo()) {
                return;
            }
        }
        if (typeof onUndo3D === "function") {
            if (onUndo3D()) {
                addLog("UI", "Undo 3D action");
                showToastNotification(uiText("Undo (3D Object)", "Отменено (3D Объект)"));
                return;
            }
        } else if (typeof window.__vfxPopUndo === "function") {
            if (window.__vfxPopUndo()) {
                addLog("UI", "Undo 3D action");
                showToastNotification(uiText("Undo (3D Object)", "Отменено (3D Объект)"));
                return;
            }
        }
        if (performStoryboardUndo()) {
            return;
        }
        showToastNotification(uiText("Undo: No history", "Отмена: нет шагов"));
    }

    function handleEditRedo() {
        if (mainViewDim === "1D" && typeof active1DRedoFn === "function") {
            if (active1DRedoFn()) {
                addLog("UI", "Redo 1D paint action");
                showToastNotification(uiText("Redo (Image layer)", "Повторено (слой Image)"));
                return;
            }
        }
        if (mainViewDim === "BOARD" || activeTab === "storyboard") {
            if (performStoryboardRedo()) {
                return;
            }
        }
        if (performStoryboardRedo()) {
            return;
        }
        showToastNotification(uiText("Redo: No steps", "Повтор: нет шагов"));
    }

    function handleClearStoryboard() {
        showDeleteConfirmModal({
            title: uiText("Clear Storyboard Canvas", "Очистить холст раскадровки"),
            message: uiText(
                "Remove all shot cards, text notes, and links from the storyboard canvas? (This action can be undone with Ctrl+Z or Edit → Undo)",
                "Удалить все кадры, текстовые карточки и связи с доски раскадровки? (Действие можно отменить через Ctrl+Z или меню Правка → Отменить)"
            ),
            onConfirm: () => {
                pushStoryboardUndoSnapshot(uiText("Clear Storyboard Canvas", "Очистка холста раскадровки"));
                storyboardCards = [];
                storyboardLinks = [];
                mediaTexts = [];
                activeTextId = null;
                saveProjectTexts();
                if (typeof saveCurrentProject === "function") saveCurrentProject();
                addLog("UI", "Cleared storyboard canvas (Cards + Texts + Links)");
                renderMainViewport();
                renderTopViewportBar();
                if (typeof renderDetailsInstances === "function") renderDetailsInstances();
                if (activeTab === "storyboard" && typeof renderActiveCustomTab === "function") renderActiveCustomTab();
                showToastNotification(uiText("Storyboard cleared (Press Ctrl+Z to undo)", "Раскадровка очищена (Нажмите Ctrl+Z для отмены)"));
            }
        });
    }

